test('adds positive numbers', () => assert.equal(sum(2, 3), 5));

test('adds zero', () => {
  assert.equal(sum(0, 3), 3);
  assert.equal(sum(3, 0), 3);
  assert.equal(sum(0, 0), 0);
});

test('adds negative numbers', () => {
  assert.equal(sum(-2, -3), -5);
  assert.equal(sum(-2, 3), 1);
  assert.equal(sum(2, -3), -1);
});

